1	/*
2	 * sensortest.c - watch all doorway sensors together (libgpiod v2).
3	 *
4	 * Grown from tools/beamtest/beamtest.c: same poll loop, signal handling,
5	 * and cleanup, but one line request now covers every line in the sensor
6	 * table below, each with the bias and debounce its circuit needs.
7	 *
8	 * The two beams will be mounted one above the other (beam_lo under
9	 * beam_hi; not mounted yet) to tell human-sized from pet-sized activity;
10	 * they are not used for direction.
11	 *
12	 * Every edge is printed with the sensor name and its new state, and the
13	 * same line is appended to a log file (default events.log, or the path
14	 * given as the only argument). The log is fsync'd after each batch of
15	 * events; if opening, writing, or syncing it fails, the program exits
16	 * with an error rather than keep running without saving events. All
17	 * lines are inputs; no line is ever configured as an output.
18	 *
19	 * Usage: sensortest [logfile]
20	 * Stop with Ctrl+C (SIGINT) or SIGTERM; all resources are released.
21	 * `make test` checks the applied line settings and a clean ASan exit.
22	 */
23	#define _POSIX_C_SOURCE 200809L
24	
25	#include <errno.h>
26	#include <fcntl.h>
27	#include <gpiod.h>
28	#include <poll.h>
29	#include <signal.h>
30	#include <stddef.h>
31	#include <stdint.h>
32	#include <stdio.h>
33	#include <stdlib.h>
34	#include <string.h>
35	#include <time.h>
36	#include <unistd.h>
37	
38	#define CHIP_PATH   "/dev/gpiochip0"  /* pinctrl-rp1 on the Pi 5 */
39	#define CONSUMER    "sensortest"
40	#define EVENT_BUF   16                /* edge events read per wakeup */
41	#define POLL_MS     500               /* max wait before re-checking stop flag */
42	#define DEFAULT_LOG "events.log"      /* relative to the current directory */
43	#define LOG_LINE    256               /* max bytes in one formatted line */
44	
45	struct sensor {
46		const char *name;
47		unsigned int offset;       /* BCM GPIO number == line offset */
48		enum gpiod_line_bias bias;
49		unsigned long debounce_us; /* 0 = no debounce */
50		const char *high_label;    /* state when the line reads HIGH */
51		const char *low_label;     /* state when the line reads LOW */
52	};
53	
54	/*
55	 * Beams (physical pins 11 and 15): the receiver signal comes through an
56	 * external 100k/100k divider, so an internal pull would shift it; no
57	 * debounce, since delaying edges would distort when both beams overlap.
58	 * Door (physical pin 13): the reed switch only shorts the line to ground,
59	 * so it needs the pull-up; its contacts bounce, so debounce 50 ms.
60	 */
61	static const struct sensor sensors[] = {
62		/* name      GPIO  bias                      debounce  high     low */
63		{ "beam_lo", 17u,  GPIOD_LINE_BIAS_DISABLED, 0,        "clear", "blocked" },
64		{ "beam_hi", 22u,  GPIOD_LINE_BIAS_DISABLED, 0,        "clear", "blocked" },
65		{ "door",    27u,  GPIOD_LINE_BIAS_PULL_UP,  50000,    "open",  "closed" },
66	};
67	
68	#define NUM_SENSORS (sizeof(sensors) / sizeof(sensors[0]))
69	
70	static volatile sig_atomic_t stop_requested = 0;
71	
72	static const char *log_path = DEFAULT_LOG;
73	static int log_fd = -1;
74	
75	static void on_signal(int signo)
76	{
77		(void)signo;
78		stop_requested = 1;
79	}
80	
81	/* Return the sensor on this line offset, or NULL if none is. */
82	static const struct sensor *sensor_by_offset(unsigned int offset)
83	{
84		for (size_t i = 0; i < NUM_SENSORS; i++) {
85			if (sensors[i].offset == offset)
86				return &sensors[i];
87		}
88		return NULL;
89	}
90	
91	/* Format local wall-clock time, e.g. "2026-10-14 09:30:01.123", into buf. */
92	static void format_wall_time(char *buf, size_t size)
93	{
94		struct timespec ts;
95		struct tm tm;
96		char secs[32];
97	
98		clock_gettime(CLOCK_REALTIME, &ts);
99		localtime_r(&ts.tv_sec, &tm);
100		strftime(secs, sizeof(secs), "%Y-%m-%d %H:%M:%S", &tm);
101		snprintf(buf, size, "%s.%03ld", secs, ts.tv_nsec / 1000000L);
102	}
103	
104	/* Write all len bytes, retrying short writes. Returns 0 or -1 (errno set). */
105	static int write_all(int fd, const char *buf, size_t len)
106	{
107		while (len > 0) {
108			ssize_t n = write(fd, buf, len);
109	
110			if (n < 0) {
111				if (errno == EINTR)
112					continue; /* interrupted before writing: retry */
113				return -1;
114			}
115			buf += n;
116			len -= (size_t)n;
117		}
118		return 0;
119	}
120	
121	/*
122	 * Send one formatted line to the terminal and append it to the log.
123	 * The line is not on disk until sync_log() runs. Returns 0 or -1.
124	 */
125	static int output_line(const char *line, int len)
126	{
127		if (len < 0 || len >= LOG_LINE) {
128			fprintf(stderr, "sensortest: log line too long\n");
129			return -1;
130		}
131		fputs(line, stdout);
132		fflush(stdout);
133		if (write_all(log_fd, line, (size_t)len) < 0) {
134			fprintf(stderr, "sensortest: write %s: %s\n", log_path,
135				strerror(errno));
136			return -1;
137		}
138		return 0;
139	}
140	
141	/* Block until everything written to the log is on disk. Returns 0 or -1. */
142	static int sync_log(void)
143	{
144		if (fsync(log_fd) < 0) {
145			fprintf(stderr, "sensortest: fsync %s: %s\n", log_path,
146				strerror(errno));
147			return -1;
148		}
149		return 0;
150	}
151	
152	/* Record one sensor-state line. mono_ns is a CLOCK_MONOTONIC timestamp. */
153	static int record_state(const struct sensor *s, const char *tag,
154				uint64_t mono_ns, int high)
155	{
156		char wall[48];
157		char line[LOG_LINE];
158		int len;
159	
160		format_wall_time(wall, sizeof(wall));
161		len = snprintf(line, sizeof(line),
162			       "%s [mono %llu.%09llu] %-7s (GPIO%u) %-7s %s\n", wall,
163			       (unsigned long long)(mono_ns / 1000000000ull),
164			       (unsigned long long)(mono_ns % 1000000000ull),
165			       s->name, s->offset, tag,
166			       high ? s->high_label : s->low_label);
167		return output_line(line, len);
168	}
169	
170	/* Record a session marker such as "start" or "stop". */
171	static int record_marker(const char *what)
172	{
173		char wall[48];
174		char line[LOG_LINE];
175		int len;
176	
177		format_wall_time(wall, sizeof(wall));
178		len = snprintf(line, sizeof(line), "%s sensortest %s\n", wall, what);
179		return output_line(line, len);
180	}
181	
182	static uint64_t mono_now_ns(void)
183	{
184		struct timespec ts;
185	
186		clock_gettime(CLOCK_MONOTONIC, &ts);
187		return (uint64_t)ts.tv_sec * 1000000000ull + (uint64_t)ts.tv_nsec;
188	}
189	
190	static int install_signal_handlers(void)
191	{
192		struct sigaction sa;
193	
194		memset(&sa, 0, sizeof(sa));
195		sa.sa_handler = on_signal;
196		sigemptyset(&sa.sa_mask);
197		sa.sa_flags = 0; /* no SA_RESTART: let poll() return EINTR */
198	
199		if (sigaction(SIGINT, &sa, NULL) < 0 ||
200		    sigaction(SIGTERM, &sa, NULL) < 0) {
201			perror("sigaction");
202			return -1;
203		}
204		return 0;
205	}
206	
207	/*
208	 * Add every sensor in the table to line_cfg. One settings object is
209	 * reused: add_line_settings copies it, so changing the bias afterwards
210	 * does not affect lines already added.
211	 */
212	static int add_sensor_lines(struct gpiod_line_config *line_cfg,
213				    struct gpiod_line_settings *settings)
214	{
215		for (size_t i = 0; i < NUM_SENSORS; i++) {
216			const struct sensor *s = &sensors[i];
217	
218			if (gpiod_line_settings_set_bias(settings, s->bias)) {
219				perror("gpiod_line_settings_set_bias");
220				return -1;
221			}
222			gpiod_line_settings_set_debounce_period_us(settings,
223								   s->debounce_us);
224			if (gpiod_line_config_add_line_settings(line_cfg, &s->offset, 1,
225								settings)) {
226				perror("gpiod_line_config_add_line_settings");
227				return -1;
228			}
229		}
230		return 0;
231	}
232	
233	/* Record every pending edge event, then sync the log. Returns 0 or -1. */
234	static int drain_events(struct gpiod_line_request *req,
235				struct gpiod_edge_event_buffer *buf)
236	{
237		int n = gpiod_line_request_read_edge_events(req, buf, EVENT_BUF);
238	
239		if (n < 0) {
240			perror("gpiod_line_request_read_edge_events");
241			return -1;
242		}
243		for (int i = 0; i < n; i++) {
244			struct gpiod_edge_event *ev =
245				gpiod_edge_event_buffer_get_event(buf, (unsigned long)i);
246			unsigned int offset = gpiod_edge_event_get_line_offset(ev);
247			const struct sensor *s = sensor_by_offset(offset);
248			int rising = gpiod_edge_event_get_event_type(ev) ==
249				     GPIOD_EDGE_EVENT_RISING_EDGE;
250	
251			if (!s) {
252				/* Cannot happen: we only requested table lines. */
253				fprintf(stderr, "event on unexpected line %u\n", offset);
254				continue;
255			}
256			if (record_state(s, rising ? "rising" : "falling",
257					 gpiod_edge_event_get_timestamp_ns(ev),
258					 rising) < 0)
259				return -1;
260		}
261		return sync_log(); /* one fsync per batch, not per line */
262	}
263	
264	/* Record the current level of every sensor. Returns 0 or -1 on error. */
265	static int record_initial_states(struct gpiod_line_request *req)
266	{
267		uint64_t now = mono_now_ns();
268	
269		for (size_t i = 0; i < NUM_SENSORS; i++) {
270			const struct sensor *s = &sensors[i];
271			enum gpiod_line_value val =
272				gpiod_line_request_get_value(req, s->offset);
273	
274			if (val == GPIOD_LINE_VALUE_ERROR) {
275				perror("gpiod_line_request_get_value");
276				return -1;
277			}
278			if (record_state(s, "initial", now,
279					 val == GPIOD_LINE_VALUE_ACTIVE) < 0)
280				return -1;
281		}
282		return 0;
283	}
284	
285	int main(int argc, char **argv)
286	{
287		struct gpiod_chip *chip = NULL;
288		struct gpiod_line_settings *settings = NULL;
289		struct gpiod_line_config *line_cfg = NULL;
290		struct gpiod_request_config *req_cfg = NULL;
291		struct gpiod_line_request *req = NULL;
292		struct gpiod_edge_event_buffer *evbuf = NULL;
293		int ret = EXIT_FAILURE;
294	
295		if (argc > 2) {
296			fprintf(stderr, "usage: %s [logfile]\n", argv[0]);
297			return EXIT_FAILURE;
298		}
299		if (argc == 2)
300			log_path = argv[1];
301	
302		if (install_signal_handlers() < 0)
303			return EXIT_FAILURE;
304	
305		/*
306		 * Append so earlier runs are kept. 0600: the event log reveals when
307		 * someone is home, so only the owner may read it. The mode applies
308		 * only when the file is created; an existing file keeps its mode.
309		 */
310		log_fd = open(log_path, O_WRONLY | O_CREAT | O_APPEND | O_CLOEXEC,
311			      0600);
312		if (log_fd < 0) {
313			fprintf(stderr, "sensortest: open %s: %s\n", log_path,
314				strerror(errno));
315			goto out;
316		}
317	
318		chip = gpiod_chip_open(CHIP_PATH);
319		if (!chip) {
320			perror("gpiod_chip_open " CHIP_PATH);
321			goto out;
322		}
323	
324		/*
325		 * Settings shared by every line: input, both edges, monotonic
326		 * timestamps. Bias and debounce are set per sensor in add_sensor_lines.
327		 */
328		settings = gpiod_line_settings_new();
329		if (!settings) {
330			perror("gpiod_line_settings_new");
331			goto out;
332		}
333		if (gpiod_line_settings_set_direction(settings,
334						      GPIOD_LINE_DIRECTION_INPUT) ||
335		    gpiod_line_settings_set_edge_detection(settings,
336							   GPIOD_LINE_EDGE_BOTH) ||
337		    gpiod_line_settings_set_event_clock(settings,
338							GPIOD_LINE_CLOCK_MONOTONIC)) {
339			perror("gpiod_line_settings_set_*");
340			goto out;
341		}
342	
343		line_cfg = gpiod_line_config_new();
344		if (!line_cfg) {
345			perror("gpiod_line_config_new");
346			goto out;
347		}
348		if (add_sensor_lines(line_cfg, settings) < 0)
349			goto out;
350	
351		req_cfg = gpiod_request_config_new();
352		if (!req_cfg) {
353			perror("gpiod_request_config_new");
354			goto out;
355		}
356		gpiod_request_config_set_consumer(req_cfg, CONSUMER);
357	
358		req = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
359		if (!req) {
360			perror("gpiod_chip_request_lines (line busy or no permission?)");
361			goto out;
362		}
363	
364		evbuf = gpiod_edge_event_buffer_new(EVENT_BUF);
365		if (!evbuf) {
366			perror("gpiod_edge_event_buffer_new");
367			goto out;
368		}
369	
370		printf("sensortest: watching %zu lines on %s, logging to %s. "
371		       "Ctrl+C to stop.\n", NUM_SENSORS, CHIP_PATH, log_path);
372		/* Initial states, read after the request so no edge is missed. */
373		if (record_marker("start") < 0 || record_initial_states(req) < 0 ||
374		    sync_log() < 0)
375			goto out;
376	
377		struct pollfd pfd = {
378			.fd = gpiod_line_request_get_fd(req),
379			.events = POLLIN,
380		};
381	
382		while (!stop_requested) {
383			int pr = poll(&pfd, 1, POLL_MS);
384	
385			if (pr < 0) {
386				if (errno == EINTR)
387					continue; /* signal: loop re-checks the flag */
388				perror("poll");
389				goto out;
390			}
391			if (pr == 0)
392				continue; /* timeout, nothing happened */
393			if (pfd.revents & (POLLERR | POLLHUP | POLLNVAL)) {
394				fprintf(stderr, "poll: error on line request fd\n");
395				goto out;
396			}
397			if (drain_events(req, evbuf) < 0)
398				goto out;
399		}
400	
401		printf("sensortest: stop requested, releasing GPIO lines\n");
402		if (record_marker("stop") < 0 || sync_log() < 0)
403			goto out;
404		ret = EXIT_SUCCESS;
405	
406	out:
407		/* Free in reverse order of creation; all are safe to skip if NULL. */
408		if (evbuf)
409			gpiod_edge_event_buffer_free(evbuf);
410		if (req)
411			gpiod_line_request_release(req);
412		if (req_cfg)
413			gpiod_request_config_free(req_cfg);
414		if (line_cfg)
415			gpiod_line_config_free(line_cfg);
416		if (settings)
417			gpiod_line_settings_free(settings);
418		if (chip)
419			gpiod_chip_close(chip);
420		if (log_fd >= 0)
421			close(log_fd); /* data was already fsync'd on success */
422		return ret;
423	}
