2	 * sensortest.c - watch all doorway sensors together (libgpiod v2).
3	 *
4	 * Grown from tools/beamtest/beamtest.c: same poll loop, signal handling,
5	 * and cleanup, but one line request now covers every line in the sensor
6	 * table below, each with the bias and debounce its circuit needs.
7	 *
8	 * The two beams will be mounted one above the other (beam_lo under
9	 * beam_hi; not mounted yet) to tell human-sized from pet-sized activity;
10	 * they are not used for direction.
11	 *
12	 * Every edge is printed with the sensor name and its new state, and the
13	 * same line is appended to a log file (default events.log, or the path
14	 * given as the only argument). The log is fsync'd after each batch of
15	 * events; if opening, writing, or syncing it fails, the program exits
16	 * with an error rather than keep running without saving events. All
17	 * lines are inputs; no line is ever configured as an output.
18	 *
19	 * Usage: sensortest [logfile]
20	 * Stop with Ctrl+C (SIGINT) or SIGTERM; all resources are released.
21	 * `make test` checks the applied line settings and a clean ASan exit.
22	 */
23	#define _POSIX_C_SOURCE 200809L
24	
25	#include <errno.h>
26	#include <fcntl.h>
27	#include <gpiod.h>
28	#include <poll.h>
29	#include <signal.h>
30	#include <stddef.h>
31	#include <stdint.h>
32	#include <stdio.h>
33	#include <stdlib.h>
34	#include <string.h>
35	#include <time.h>
36	#include <unistd.h>
37	
38	#define CHIP_PATH   "/dev/gpiochip0"  /* pinctrl-rp1 on the Pi 5 */
39	#define CONSUMER    "sensortest"
40	#define EVENT_BUF   16                /* edge events read per wakeup */
41	#define POLL_MS     500               /* max wait before re-checking stop flag */
42	#define DEFAULT_LOG "events.log"      /* relative to the current directory */
43	#define LOG_LINE    256               /* max bytes in one formatted line */
44	
45	struct sensor {
46		const char *name;
47		unsigned int offset;       /* BCM GPIO number == line offset */
48		enum gpiod_line_bias bias;
49		unsigned long debounce_us; /* 0 = no debounce */
50		const char *high_label;    /* state when the line reads HIGH */
51		const char *low_label;     /* state when the line reads LOW */
52	};
53	
54	/*
55	 * Beams (physical pins 11 and 15): the receiver signal comes through an
56	 * external 100k/100k divider, so an internal pull would shift it; no
57	 * debounce, since delaying edges would distort when both beams overlap.
58	 * Door (physical pin 13): the reed switch only shorts the line to ground,
59	 * so it needs the pull-up; its contacts bounce, so debounce 50 ms.
60	 */
61	static const struct sensor sensors[] = {
62		/* name      GPIO  bias                      debounce  high     low */
63		{ "beam_lo", 17u,  GPIOD_LINE_BIAS_DISABLED, 0,        "clear", "blocked" },
64		{ "beam_hi", 22u,  GPIOD_LINE_BIAS_DISABLED, 0,        "clear", "blocked" },
65		{ "door",    27u,  GPIOD_LINE_BIAS_PULL_UP,  50000,    "open",  "closed" },
66	};
