91	/* Format local wall-clock time, e.g. "2026-10-14 09:30:01.123", into buf. */
92	static void format_wall_time(char *buf, size_t size)
93	{
94		struct timespec ts;
95		struct tm tm;
96		char secs[32];
97	
98		clock_gettime(CLOCK_REALTIME, &ts);
99		localtime_r(&ts.tv_sec, &tm);
